import type { Ticket } from '@api/api-types';

interface TicketDisplayDateTime {
  date: string;
  time: string;
}

const COVERAGE_TYPE_ALIASES: Record<string, string> = {
  gp: 'gp',
  'general practice': 'gp',
  'general-practice': 'gp',
  general_practice: 'gp',
  'general practitioner': 'gp',
  普通科: 'gp',
  普通科医生: 'gp',
  全科医生: 'gp',
  全科醫生: 'gp',
};

const isResolvedTranslation = (value: string, key: string): boolean =>
  Boolean(value) &&
  value !== key &&
  !value.toLowerCase().includes('missing');

const translateCoverageType = (
  rawValue: string,
  translate: (key: string) => string
): string => {
  const trimmed = rawValue.trim();

  if (!trimmed) {
    return '';
  }

  const coverageType =
    COVERAGE_TYPE_ALIASES[trimmed.toLowerCase()] ?? trimmed.toLowerCase();
  const coverageKey = `dsi.memberCoverage.${coverageType}`;
  const coverageLabel = translate(coverageKey).trim();

  if (isResolvedTranslation(coverageLabel, coverageKey)) {
    return coverageLabel;
  }

  const directLabel = translate(trimmed).trim();

  if (isResolvedTranslation(directLabel, trimmed)) {
    return directLabel;
  }

  return '';
};

export const getTicketDoctorTypeLabel = (
  ticket: Ticket,
  translate: (key: string) => string
): string => {
  const typeLabel = ticket.doctor?.type
    ? translateCoverageType(ticket.doctor.type, translate)
    : '';

  if (typeLabel) {
    return typeLabel;
  }

  const specialtyLabels = (ticket.doctor?.specialties ?? [])
    .map((specialty: string): string =>
      translateCoverageType(specialty, translate)
    )
    .filter((label: string): boolean => label.length > 0);

  if (specialtyLabels.length > 0) {
    return specialtyLabels.join(', ');
  }

  const specialtyType = ticket.valueAsJson?.specialtyType
    ? translateCoverageType(ticket.valueAsJson.specialtyType, translate)
    : '';

  if (specialtyType) {
    return specialtyType;
  }

  return translate('no_data');
};

export const getTicketDisplayDateTimeSource = (
  ticket: Ticket
): string | undefined => {
  if (ticket.startTime) {
    return ticket.startTime;
  }

  return (
    ticket.expectedCallTime ||
    ticket.expectedCallDateTimeUtc ||
    ticket.calledDateTimeUtc ||
    ticket.consultation?.visitTime ||
    undefined
  );
};

export const formatTicketDisplayDateTime = (
  isoDateTime: string | undefined,
  language: string,
  timeZone?: string
): TicketDisplayDateTime => {
  const invalid: TicketDisplayDateTime = { date: '--', time: '--' };

  if (!isoDateTime) {
    return invalid;
  }

  const date = new Date(isoDateTime);

  if (Number.isNaN(date.getTime())) {
    return invalid;
  }

  const locale = language || 'en';
  const localeOptions: Intl.DateTimeFormatOptions = {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    ...(timeZone ? { timeZone } : {}),
  };
  const formattedDate = new Intl.DateTimeFormat(locale, localeOptions).format(
    date
  );
  let displayDate = formattedDate;

  if (locale !== 'zh-Hant' && locale !== 'zh-Hans') {
    const parts = new Intl.DateTimeFormat('en-US', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
      ...(timeZone ? { timeZone } : {}),
    }).formatToParts(date);
    const day = parts.find((part) => part.type === 'day')?.value;
    const month = parts.find((part) => part.type === 'month')?.value;
    const year = parts.find((part) => part.type === 'year')?.value;
    displayDate =
      day && month && year ? `${day} ${month}. ${year}` : formattedDate;
  }

  const formattedTime = new Intl.DateTimeFormat('en-GB', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
    ...(timeZone ? { timeZone } : {}),
  }).format(date);

  return {
    date: displayDate,
    time: formattedTime,
  };
};

export const getTicketDisplayDateTime = (
  ticket: Ticket,
  language: string,
  timeZone?: string
): TicketDisplayDateTime =>
  formatTicketDisplayDateTime(
    getTicketDisplayDateTimeSource(ticket),
    language,
    timeZone
  );

