const SPECIALTY_ALIASES: Record<string, string> = {
  gp: 'general_practitioner',
  'general practice': 'general_practitioner',
  'general-practice': 'general_practitioner',
  general_practice: 'general_practitioner',
  'general practitioner': 'general_practitioner',
  普通科: 'general_practitioner',
  普通科医生: 'general_practitioner',
};

const translateSpecialtyLabel = (name: string): string => {
  const trimmed = name.trim();

  if (!trimmed) {
    return '';
  }

  const lookupKey = SPECIALTY_ALIASES[trimmed.toLowerCase()] ?? trimmed;
  const translated = constants.i18n.t(lookupKey);

  return translated.includes('missing') ? trimmed : translated;
};

const getDoctorSpecialty = (ticket: Ticket): string => {
  const specialties = (ticket.doctor?.specialties ?? [])
    .map(translateSpecialtyLabel)
    .filter((label: string): boolean => label.length > 0);

  if (specialties.length > 0) {
    return specialties.join(', ');
  }

  const typeLabel = ticket.doctor?.type
    ? translateSpecialtyLabel(ticket.doctor.type)
    : '';

  if (typeLabel) {
    return typeLabel;
  }

  const specialtyType = ticket.valueAsJson?.specialtyType
    ? translateSpecialtyLabel(ticket.valueAsJson.specialtyType)
    : '';

  if (specialtyType) {
    return specialtyType;
  }

  return constants.i18n.t('no_data');
};

const getAppointmentDateTimeValue = (ticket: Ticket): string | undefined => {
  if (ticket.startTime) {
    return ticket.startTime;
  }

  const peopleAhead = ticket.currentPosition
    ? (ticket.currentPosition ?? 1) - 1
    : '';

  return peopleAhead ? ticket.expectedCallTime : undefined;
};

const getTicketDateTime = (ticket: Ticket): TicketDateTime => {
  const dateTime = dayjs(getAppointmentDateTimeValue(ticket));

  if (!dateTime.isValid()) {
    return { date: '--', time: '--' };
  }

  return {
    date: dateTime.format('YYYY-MM-DD'),
    time: dateTime.format('HH:mm'),
  };
};

