import type { Ticket } from '../src/api/api-types';
import {
  formatTicketDisplayDateTime,
  getTicketDisplayDateTime,
  getTicketDisplayDateTimeSource,
  getTicketDoctorTypeLabel,
} from '../src/helper/ticket-display-helper';

const translate = (key: string): string => {
  const translations: Record<string, string> = {
    'dsi.memberCoverage.gp': '全科医生',
    no_data: 'No data',
    dermatology: 'Dermatology',
  };

  return translations[key] ?? key;
};

const createTicket = (overrides: Partial<Ticket> = {}): Ticket =>
  ({
    id: 'ticket-1',
    doctor: {
      id: 'doctor-1',
      name: '陈戴傅',
      type: 'GP',
      specialties: ['GP'],
      specialtyIds: ['gp'],
    },
    valueAsJson: {
      specialtyType: 'GP',
    },
    startTime: null,
    expectedCallTime: '2026-04-21T09:26:00.000Z',
    expectedCallDateTimeUtc: '2026-04-21T09:26:00.000Z',
    currentPosition: 1,
    consultation: {
      visitTime: '2026-01-01T00:00:00.000Z',
    },
    ...overrides,
  }) as Ticket;

describe('ticket display helper', () => {
  test('uses the appointment coverage label for GP instead of the raw type code', () => {
    expect(getTicketDoctorTypeLabel(createTicket(), translate)).toBe(
      '全科医生'
    );
    expect(
      getTicketDoctorTypeLabel(
        createTicket({
          doctor: {
            id: 'doctor-1',
            name: '陈戴傅',
            type: 'GP',
            specialties: ['dermatology'],
            specialtyIds: ['dermatology'],
          },
        }),
        translate
      )
    ).toBe('全科医生');
  });

  test('prefers startTime and otherwise uses expectedCallTime', () => {
    const estimated = createTicket({ startTime: null });
    const scheduled = createTicket({
      startTime: '2026-04-21T09:26:00.000Z',
      expectedCallTime: '2026-01-01T00:00:00.000Z',
    });

    expect(getTicketDisplayDateTimeSource(estimated)).toBe(
      '2026-04-21T09:26:00.000Z'
    );
    expect(getTicketDisplayDateTimeSource(scheduled)).toBe(
      '2026-04-21T09:26:00.000Z'
    );
  });

  test('formats date and time in Asia/Shanghai like the appointment details page', () => {
    expect(
      formatTicketDisplayDateTime(
        '2026-04-21T09:26:00.000Z',
        'zh-Hans',
        'Asia/Shanghai'
      )
    ).toEqual({
      date: '2026年4月21日',
      time: '17:26',
    });

    expect(
      getTicketDisplayDateTime(
        createTicket({ startTime: null }),
        'zh-Hans',
        'Asia/Shanghai'
      )
    ).toEqual({
      date: '2026年4月21日',
      time: '17:26',
    });
  });
});

