import type { Dependants } from '@api/api-types';

export const resolveSelectedDependant = (
  dependants: Dependants[],
  selectedDependant: Dependants | null | undefined
): Dependants | null => {
  if (!dependants.length) {
    return null;
  }

  if (selectedDependant?.id) {
    const matched = dependants.find(
      (item: Dependants): boolean => item.id === selectedDependant.id
    );

    if (matched) {
      return matched;
    }
  }

  return dependants[0];
};

