import type { Dependants } from '../src/api/api-types';
import { resolveSelectedDependant } from '../src/helper/selected-dependant-helper';

const createDependant = (
  overrides: Partial<Dependants> = {}
): Dependants => ({
  id: 'dependant-1',
  name: 'New Town Levinal',
  contact: '+86-18316022516',
  type: 'Dependant',
  ...overrides,
});

describe('resolveSelectedDependant', () => {
  test('returns the first dependant when none is selected', () => {
    const first = createDependant();
    const second = createDependant({
      id: 'dependant-2',
      name: 'Tontonton',
      contact: '+852-912312345',
    });

    expect(resolveSelectedDependant([first, second], null)).toEqual(first);
  });

  test('keeps a selected dependant that still exists', () => {
    const first = createDependant();
    const second = createDependant({
      id: 'dependant-2',
      name: 'Tontonton',
      contact: '+852-912312345',
    });

    expect(resolveSelectedDependant([first, second], second)).toEqual(second);
  });

  test('falls back to the first dependant when the selected id is missing', () => {
    const first = createDependant();
    const removed = createDependant({
      id: 'removed',
      name: 'Removed',
    });

    expect(resolveSelectedDependant([first], removed)).toEqual(first);
  });

  test('returns null when the list is empty', () => {
    expect(resolveSelectedDependant([], createDependant())).toBeNull();
  });
});

